/* ============ 通用_美化 · 浅紫极简 ============ */

.mix-game,
.mix-game *,
.mix-game *::before,
.mix-game *::after {
  box-sizing: border-box;
}

.mix-game {
  --fq-white: rgba(255, 255, 255, 0.95);
  --fq-white-soft: rgba(255, 255, 255, 0.8);
  --fq-ink: #24537f;
  --fq-line: rgba(255, 255, 255, 0.4);

  position: relative;
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  color: var(--fq-white);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "HarmonyOS Sans SC",
    "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.62;
  background: #a8cdf0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ============ 对话滚动区 ============ */
.mix-game-scroll {
  position: relative;
  z-index: 1;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px 14px;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

.mix-game-scroll::-webkit-scrollbar {
  width: 6px;
}

.mix-game-scroll::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.5);
}

/* ============ 玩家轮 ============ */
.mix-user-turn {
  align-self: stretch;
  display: flex;
  justify-content: flex-end;
  background: none;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.mix-user-turn::before,
.mix-user-turn::after {
  content: none;
  display: none;
  background: none;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.mix-user-bubble {
  max-width: 100%;
  padding: 0;
  margin: 0;
  background: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  color: #E6E6FA;
  font-size: 14px;
  line-height: 1.62;
  text-align: right;
  word-break: break-word;
  white-space: pre-wrap;
  filter: none;
}

.mix-user-bubble::before,
.mix-user-bubble::after {
  content: none;
  display: none;
  background: none;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* ============ AI 轮 ============ */
.mix-assistant-turn {
  align-self: stretch;
  max-width: none;
}

/* ============ 正文语义 ============ */
.mix-prose {
  color: var(--fq-white);
  font-size: 14px;
  line-height: 1.8;
}

.mix-para {
  margin: 0 0 0.7em;
  text-indent: 2em;
  color: var(--fq-white);
  font-size: 14px;
  line-height: 1.62;
}

.mix-narration {
  display: block;
  margin: 0.5em 0;
  text-indent: 2em;
  color: var(--fq-white);
  font-size: 14px;
  line-height: 1.62;
}

.mix-scene {
  display: block;
  margin: 4px 0 10px;
  text-align: center;
  text-indent: 0;
  font-size: 12.5px;
  letter-spacing: 0.2em;
  color: var(--fq-white-soft);
}

/* 角色发言：白 → 浅紫 渐变文字 */
.mix-dialogue {
  display: block;
  margin: 0.55em 0;
  text-indent: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.62;
  word-break: break-word;
  color: #bcdcfb;
  background: linear-gradient(135deg, #ffffff 0%, #b39ae0 45%, #b39ae0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 1px 2px rgba(30, 70, 120, 0.45));
}

.mix-user-bubble .mix-dialogue {
  margin: 0;
  filter: none;
}

.mix-thought {
  display: block;
  margin: 0.55em 0;
  padding: 6px 0 6px 13px;
  text-indent: 0;
  border-left: 2px solid rgba(255, 255, 255, 0.7);
  color: var(--fq-white-soft);
  font-size: 14px;
  font-style: italic;
  line-height: 1.62;
}

.mix-accent {
  color: #ffffff;
  font-weight: 700;
}

/* ============ 细节 ============ */
.mix-game ::selection {
  background: rgba(255, 255, 255, 0.6);
  color: var(--fq-ink);
}

@media (max-width: 380px) {
  .mix-game-scroll {
    padding: 12px 10px;
    gap: 12px;
  }
}
